//! Public TMDB artwork and isolated account image storage.
//! Private file snapshots use the separate account-bound file_artwork route.
use crate::settings::AppError;
use std::{path::PathBuf,time::{Duration,SystemTime},sync::{Mutex,Arc}};
use sha2::{Digest,Sha256};
use tauri::Manager;
const MAX_IMAGE:u64=8*1024*1024;
const MAX_CACHE:u64=128*1024*1024;
const TTL:Duration=Duration::from_secs(7*24*3600);
fn err()->AppError{AppError::new("ARTWORK_CACHE","媒体图片暂不可用",true)}
pub struct ArtworkCache{directory:PathBuf,lock:Arc<Mutex<()>>}
impl ArtworkCache{
 pub fn new(directory:PathBuf)->Self{Self{directory,lock:Arc::new(Mutex::new(()))}}
 pub fn account_cache(&self,account:&str)->Self{Self{directory:self.directory.join(format!("account-{:x}",Sha256::digest(account.as_bytes()))),lock:self.lock.clone()}}
 pub fn remove_account(&self,account:&str){if let Ok(_guard)=self.lock.lock(){let _=std::fs::remove_dir_all(self.account_cache(account).directory);}}
 pub fn read_private(&self,identity:&str)->Result<Option<Vec<u8>>,AppError>{self.read(&format!("https://api.xbyvideohub.com/api/tmdb/image/{:x}",Sha256::digest(identity.as_bytes())))}
 pub fn store_private(&self,identity:&str,data:&[u8])->Result<(),AppError>{self.store(&format!("https://api.xbyvideohub.com/api/tmdb/image/{:x}",Sha256::digest(identity.as_bytes())),data)}
 fn key(url:&str)->Result<String,AppError>{let u=url::Url::parse(url).map_err(|_|err())?;if u.scheme()!="https"||u.host_str()!=Some("api.xbyvideohub.com")||u.port().is_some()||!u.username().is_empty()||u.password().is_some()||u.query().is_some()||u.fragment().is_some()||!u.path().starts_with("/api/tmdb/image/")||u.path().contains("..") {return Err(err())}Ok(format!("{:x}",Sha256::digest(url.as_bytes())))}
 fn read(&self,url:&str)->Result<Option<Vec<u8>>,AppError>{let key=Self::key(url)?;let _lock=self.lock.lock().map_err(|_|err())?;let path=self.directory.join(key);if let Ok(meta)=std::fs::metadata(&path){if meta.len()<=MAX_IMAGE&&meta.modified().ok().and_then(|t|t.elapsed().ok()).is_some_and(|age|age<TTL){let data=std::fs::read(&path).map_err(|_|err())?;if mime(&data).is_some(){return Ok(Some(data))}}let _=std::fs::remove_file(path);}Ok(None)}
 fn store(&self,url:&str,bytes:&[u8])->Result<(),AppError>{let key=Self::key(url)?;if bytes.len()as u64>MAX_IMAGE||mime(bytes).is_none(){return Err(err())}let _lock=self.lock.lock().map_err(|_|err())?;std::fs::create_dir_all(&self.directory).map_err(|_|err())?;#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::set_permissions(&self.directory,std::fs::Permissions::from_mode(0o700)).map_err(|_|err())?;}let mut files=Vec::new();let mut total=0;for item in std::fs::read_dir(&self.directory).map_err(|_|err())?.flatten(){if let Ok(meta)=item.metadata(){if meta.is_file(){total+=meta.len();files.push((meta.modified().unwrap_or(SystemTime::UNIX_EPOCH),meta.len(),item.path()));}}}files.sort_by_key(|v|v.0);for (_,size,path)in files{if total+bytes.len()as u64<=MAX_CACHE{break}std::fs::remove_file(path).map_err(|_|err())?;total=total.saturating_sub(size);}use std::io::Write;let mut temp=tempfile::NamedTempFile::new_in(&self.directory).map_err(|_|err())?;temp.write_all(bytes).map_err(|_|err())?;temp.persist(self.directory.join(key)).map_err(|_|err())?;Ok(())}
 async fn image(&self,url:&str)->Result<Vec<u8>,AppError>{if let Some(bytes)=self.read(url)?{return Ok(bytes)}Self::key(url)?;let client=crate::network_proxy::builder().timeout(Duration::from_secs(30)).build().map_err(|_|err())?;let mut response=client.get(url).send().await.map_err(|_|err())?;if !response.status().is_success()||response.content_length().is_some_and(|len|len>MAX_IMAGE){return Err(err())}let mut data=Vec::new();while let Some(chunk)=response.chunk().await.map_err(|_|err())?{if data.len()+chunk.len()>MAX_IMAGE as usize{return Err(err())}data.extend_from_slice(&chunk)}self.store(url,&data)?;Ok(data)}
}
pub fn mime(bytes:&[u8])->Option<&'static str>{if bytes.starts_with(b"\x89PNG\r\n\x1a\n"){Some("image/png")}else if bytes.starts_with(&[0xff,0xd8,0xff]){Some("image/jpeg")}else if bytes.len()>=12&&bytes.starts_with(b"RIFF")&&&bytes[8..12]==b"WEBP"{Some("image/webp")}else{None}}
pub fn register(builder:tauri::Builder<tauri::Wry>)->tauri::Builder<tauri::Wry>{builder.register_asynchronous_uri_scheme_protocol("mscache",|context,request,responder|{let app=context.app_handle().clone();let uri=request.uri().to_string();tauri::async_runtime::spawn(async move{let source=url::Url::parse(&uri).ok().and_then(|u|u.query_pairs().find(|(key,_)|key=="url").map(|(_,v)|v.into_owned()));let private=url::Url::parse(&uri).ok().is_some_and(|url|url.path()=="/file-thumbnail");let result=if private{crate::file_artwork::image(&app,&uri).await}else{match(source,app.try_state::<ArtworkCache>()){(Some(url),Some(cache))=>cache.image(&url).await,_=>Err(err())}};let response=match result{Ok(bytes)=>{let response=tauri::http::Response::builder().status(200).header("Content-Type",mime(&bytes).unwrap_or("application/octet-stream")).header("Cache-Control",if private{"no-store"}else{"max-age=86400"});let response=if private{response}else{response.header("Access-Control-Allow-Origin","*")};response.body(bytes).unwrap()},Err(_)=>tauri::http::Response::builder().status(404).header("Cache-Control","no-store").body(Vec::new()).unwrap()};responder.respond(response);});})}
#[cfg(test)]mod tests{use super::*;#[test]fn public_url_scope_rejects_credentials_redirects_and_arbitrary_hosts(){for url in ["https://example.com/api/tmdb/image/x","https://api.xbyvideohub.com/api/tmdb/image/a?token=secret","https://u:p@api.xbyvideohub.com/api/tmdb/image/x","http://api.xbyvideohub.com/api/tmdb/image/a","https://api.xbyvideohub.com/account"]{assert!(ArtworkCache::key(url).is_err());}}
#[test]fn cached_images_survive_reopen_and_corruption_is_invalidated(){let dir=tempfile::tempdir().unwrap();let url="https://api.xbyvideohub.com/api/tmdb/image/w500/a.jpg";let bytes=b"\x89PNG\r\n\x1a\nfixture";let cache=ArtworkCache::new(dir.path().into());cache.store(url,bytes).unwrap();assert_eq!(ArtworkCache::new(dir.path().into()).read(url).unwrap().unwrap(),bytes);std::fs::write(dir.path().join(ArtworkCache::key(url).unwrap()),b"<html>error</html>").unwrap();assert!(cache.read(url).unwrap().is_none());assert!(cache.store(url,b"<svg>no scripts</svg>").is_err());}}
#[cfg(test)]mod account_tests{use super::*;#[test]fn account_images_are_isolated_from_public_cache_and_removed_on_logout(){let dir=tempfile::tempdir().unwrap();let cache=ArtworkCache::new(dir.path().into());let a=cache.account_cache("a");let b=cache.account_cache("b");let bytes=b"\x89PNG\r\n\x1a\nfixture";a.store_private("server/user/item",bytes).unwrap();assert!(a.read_private("server/user/item").unwrap().is_some());assert!(b.read_private("server/user/item").unwrap().is_none());assert!(cache.read_private("server/user/item").unwrap().is_none());assert!(a.read_private("other-user/item").unwrap().is_none());cache.remove_account("a");assert!(a.read_private("server/user/item").unwrap().is_none());}}
#[cfg(test)]mod eviction_tests{use super::*;#[test]fn expiration_and_size_budget_evict_old_images(){let dir=tempfile::tempdir().unwrap();let cache=ArtworkCache::new(dir.path().into());let url="https://api.xbyvideohub.com/api/tmdb/image/w500/a.png";let bytes=b"\x89PNG\r\n\x1a\nfixture";cache.store(url,bytes).unwrap();let path=dir.path().join(ArtworkCache::key(url).unwrap());std::fs::File::options().write(true).open(&path).unwrap().set_times(std::fs::FileTimes::new().set_modified(SystemTime::UNIX_EPOCH)).unwrap();assert!(cache.read(url).unwrap().is_none());let large=dir.path().join("old-sparse");std::fs::File::create(&large).unwrap().set_len(MAX_CACHE).unwrap();cache.store(url,bytes).unwrap();assert!(!large.exists());assert!(cache.read(url).unwrap().is_some());}}
